const rubocopOut  = $('rubocop_autofix').first().json.stdout || '';
const brakemanOut = $('brakeman_security').first().json.stdout || '';
const auditOut    = $('bundler_cve_audit').first().json.stdout || '';
const erbOut      = $('erb_lint_check').first().json.stdout || '';

// ---- GitHub Actions ----
let ghFailed = false, ghLine = '';
try {
  const ghData = $('gh_actions_check').first().json;
  const run = ghData.workflow_runs && ghData.workflow_runs[0];
  if (run) {
    const conc = run.conclusion || run.status || 'unknown';
    ghFailed = (conc === 'failure');
    const icon = conc === 'success' ? '✅' : conc === 'failure' ? '🚨' : '⏳';
    ghLine = icon + ' ' + conc + (ghFailed ? '
  🔗 ' + run.html_url : '');
  } else {
    ghLine = '❓ データなし';
  }
} catch(e) {
  ghLine = '❓ 取得失敗: ' + e.message;
}


// ---- RuboCop ----
let rcFixed = 0, rcRemain = 0, rcDetails = [];
try {
  const start = rubocopOut.indexOf('{');
  const d = JSON.parse(rubocopOut.substring(start));
  const s = d.summary || {};
  rcRemain = s.offense_count || 0;
  rcFixed  = s.corrected_offense_count || 0;
  rcDetails = (d.files || [])
    .filter(f => (f.offenses||[]).length > 0)
    .flatMap(f => f.offenses.map(o =>
      f.path.split('/').slice(-2).join('/') + ':' + o.location.line + ' [' + o.cop_name + ']'))
    .slice(0, 5);
} catch(e) { rcRemain = -1; }

// ---- Brakeman ----
let bkWarn = 0, bkDetails = [];
try {
  const start = brakemanOut.indexOf('{');
  const d = JSON.parse(brakemanOut.substring(start));
  bkWarn = (d.warnings||[]).length;
  bkDetails = (d.warnings||[]).slice(0,3)
    .map(w => (w.file||'?') + ':' + (w.line||'?') + ' ' + w.warning_type + ': ' + (w.message||'').slice(0,50));
} catch(e) {}

// ---- Bundler Audit ----
const bkVuln  = auditOut.includes('Vulnerabilities found');
const bkClean = auditOut.includes('No vulnerabilities found');

// ---- ERB Lint ----
let erbErrors = 0;
const erbMatch = erbOut.match(/(\d+)\s+error/);
if (erbMatch) erbErrors = parseInt(erbMatch[1], 10);
const erbOk = erbOut.includes('No errors') || erbErrors === 0;

// ---- Format ----
const jstNow = new Date(Date.now() + 9*3600*1000)
  .toISOString().slice(0,16).replace('T',' ') + ' JST';
let hasIssues = rcRemain > 0 || bkWarn > 0 || bkVuln || ghFailed;

let msg = (hasIssues ? '⚠️' : '✅') + ' *コード品質パトロール*\n' + jstNow + '\n';
msg += '━━━━━━━━━━━━━\n';

// RuboCop
msg += '\n💎 *RuboCop*\n';
if (rcFixed > 0)  msg += '  🔧 ' + rcFixed + '件を自動修正\n';
if (rcRemain > 0) {
  msg += '  ❗ 残' + rcRemain + '件（手動対応）\n';
  rcDetails.forEach(d => { msg += '  · ' + d + '\n'; });
} else if (rcRemain === 0) {
  msg += '  ✅ 問題なし\n';
} else {
  msg += '  ❓ 解析エラー\n';
}

// ERB Lint
msg += '\n📝 *ERB Lint*\n';
if (erbErrors > 0) {
  msg += '  ⚠️ ' + erbErrors + '件のテンプレート問題\n';
} else if (erbOk) {
  msg += '  ✅ 問題なし\n';
} else {
  msg += '  ❓ チェック失敗\n';
}

// Brakeman
msg += '\n🛡 *Brakeman (Security)*\n';
if (bkWarn > 0) {
  msg += '  🚨 ' + bkWarn + '件の警告\n';
  bkDetails.forEach(d => { msg += '  · ' + d + '\n'; });
} else {
  msg += '  ✅ 脆弱性なし\n';
}

// Bundler Audit
msg += '\n📦 *Bundler Audit (CVE)*\n';
if (bkVuln) {
  msg += '  🚨 脆弱なgemを検出\n';
  auditOut.split('\n')
    .filter(l => /Name:|Advisory:|Criticality:/.test(l))
    .slice(0,6).forEach(l => { msg += '  ' + l.trim() + '\n'; });
} else if (bkClean) {
  msg += '  ✅ 既知CVEなし\n';
} else {
  msg += '  ❓ チェック失敗\n';
}

msg += '\n━━━━━━━━━━━━━\n';
msg += hasIssues ? '⚠️ 要対応あり' : '🎉 全チェック通過';
msg += '\n_IATF System Auto Patrol_';

return [{json: {message: msg, hasIssues, rcFixed, rcRemain, bkWarn, bkVuln, erbErrors}}];

